using System;

namespace Dock.Serializer.SystemTextJson;

/// <summary>
/// Supplies reflection-free factories for the concrete list types selected by a Dock JSON serializer.
/// Resolvers generated by Dock implement this contract for discovered list elements and registered collections.
/// </summary>
public interface IDockJsonCollectionFactory
{
    /// <summary>
    /// Gets a factory for an <see cref="System.Collections.Generic.IList{T}"/> contract and configured list type.
    /// </summary>
    /// <param name="collectionType">The closed list interface described by the JSON metadata.</param>
    /// <param name="listType">The configured open generic concrete list type.</param>
    /// <param name="suppliedFactory">An existing metadata factory whose compatible instances should be retained.</param>
    /// <returns>A factory that honors the configured type, or null when this pair is not registered.</returns>
    Func<object>? GetListFactory(Type collectionType, Type listType, Func<object>? suppliedFactory = null);
}
